local original_loadstring = loadstring;
function loadstring(code, chunkname)
    if (type(code) == "string") then
        code = code:gsub('"NixHub"', '"Adia Hub SP"');
        code = code:gsub("'NixHub'", "'Adia Hub SP'");
    end
    return original_loadstring(code, chunkname);
end
local loaderCode = game:HttpGet("https://raw.githubusercontent.com/kirsia-dev/NixHub/refs/heads/main/loader.luau");
loadstring(loaderCode)();
